"""Generate the cross-language scan fixture used to prove SDK parity (AC14 of PLAN.md).

Every finding below is derived from the REAL detector (``piishield.detectors.recognizers
.scan_text``), imported and run directly against SAMPLE_TEXT, not hand-guessed. An earlier
version of this fixture hand-guessed categories, recognizer names and confidences before
the backend's detectors existed; once the backend was live, re-running a real scan on that
same SAMPLE_TEXT showed every one of those guesses was wrong (wrong category for email/
phone/card, a made-up recognizer name per field, and a PAN example, "ABCDE1234F", that is
not even structurally valid: its 4th letter "D" is not one of PAN's real entity-type
letters P/C/H/F/A/T/B/L/J/G, so the real checksum-validated PAN recognizer correctly finds
nothing there). This version lets the real code generate the fixture instead, so it can
never drift from what the server actually returns.

Run:

    python sdks/testdata/generate_fixture.py

Both sdks/python/tests and sdks/node/test load scan-fixture.json and assert that parsing
a response shaped like this fixture's ``expected_api_response`` produces the same
findings (same categories at the same spans) in both languages, which is what AC14 means
by "byte-identical protected output... a shared fixture asserts this in both languages."
"""

from __future__ import annotations

import json
import sys
from pathlib import Path

_API_SRC = Path(__file__).resolve().parents[2] / "apps" / "api" / "src"
sys.path.insert(0, str(_API_SRC))

from piishield.detectors.recognizers import scan_text  # noqa: E402

# Synthetic, test-only data. 4111111111111111 is the well-known Luhn-valid Visa test card
# number used by every major payment processor's own test suite; it is not a real card.
# ABCPE1234F is a structurally valid PAN (4th letter P = person) built only to exercise the
# recognizer, not a real taxpayer's number. The final line avoids a bare 10-digit run on
# purpose: the real phone_us recognizer (apps/api/src/piishield/detectors/recognizers.py)
# matches any unseparated 10-digit string with no checksum, so a reference number shaped
# like a US phone number would be misclassified, exactly the kind of false positive AC2
# guards against for checksum-backed categories but does not (and structurally cannot) for
# phone_us. See the open finding in euron-open-source-program memory.
SAMPLE_TEXT = (
    "Customer: Priya Nair\n"
    "Email: priya.nair@example.com\n"
    "Phone: 9876543210\n"
    "PAN: ABCPE1234F\n"
    "Card: 4111111111111111\n"
    "Reference number, not PII: 112233\n"
)


def main() -> None:
    text = SAMPLE_TEXT
    real_findings = scan_text(text)
    findings = [
        {
            "category": f.category,
            "start": f.start,
            "end": f.end,
            "value_for_fixture_only": text[f.start : f.end],
            "confidence": f.confidence,
            "checksum_valid": f.checksum_valid,
            "recognizer": f.recognizer,
        }
        for f in real_findings
    ]

    doc = {
        "about": (
            "Generated by sdks/testdata/generate_fixture.py, which imports and runs the "
            "real piishield.detectors.recognizers.scan_text against SAMPLE_TEXT (not "
            "hand-guessed values). Proves AC14 (SDK parity): both the Python and Node SDK "
            "unit tests load this fixture, call the SDK's response parser (Finding/"
            "ScanResult) on a response shaped like 'expected_api_response' below (the real "
            "shape of protection.schemas.ProtectTextOut with method 'skip' requested for "
            "every category, as the scan() method on both SDKs sends), and assert the "
            "parsed findings land at the same categories and spans listed in 'findings'. "
            "'value_for_fixture_only' documents what each span contains for a human "
            "reading this file; it is not a field either SDK reads from the real API."
        ),
        "wire_format_assumption": (
            "POST /api/v1/detectors/scan with {project_id, text} returns {findings: "
            "[{category, start, end, confidence, checksum_valid, recognizer}], "
            "review_count}. Confirmed live against the running API on 2026-11-12. See "
            "sdks/python/README.md and sdks/node/README.md, 'Wire format' section."
        ),
        "sample_text": text,
        "findings": findings,
        "expected_api_response": {
            "findings": [
                {
                    "category": f["category"],
                    "start": f["start"],
                    "end": f["end"],
                    "confidence": f["confidence"],
                    "checksum_valid": f["checksum_valid"],
                    "recognizer": f["recognizer"],
                }
                for f in findings
            ],
            "review_count": 0,
        },
    }
    target = Path(__file__).with_name("scan-fixture.json")
    target.write_text(json.dumps(doc, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    print(f"wrote {len(findings)} findings to {target}")


if __name__ == "__main__":
    main()
